<script setup>
import {ref} from 'vue'
import {characters} from '../data/characters'
import {useArcade} from '../stores/arcade'
const props=defineProps({modelValue:String,locked:{type:Boolean,default:false},signup:{type:Boolean,default:false}}),emit=defineEmits(['update:modelValue']),s=useArcade(),pending=ref(null),busy=ref(false),error=ref('')
function unavailable(c){return (!props.signup&&s.data.pet.character==='diglett')||!!c.minLevel&&(props.signup||!s.user||s.level<c.minLevel)}
function choose(c){if(unavailable(c))return;if(c.id===props.modelValue&&props.locked)return;if(!props.locked){emit('update:modelValue',c.id);return}pending.value=c;error.value=''}
async function change(){if(busy.value)return;busy.value=true;error.value='';try{await s.selectCharacter(pending.value.id);pending.value=null}catch(e){error.value=e.message}finally{busy.value=false}}
</script>
<template><fieldset class="character-picker"><legend>나의 파트너 선택</legend><p>{{locked?'다른 포켓몬으로 변경할 때 5,000포인트를 사용해요. 캐릭터 변경 시 새 계열의 1단계로 돌아갑니다. 레벨·보유 아이템·스킨은 보존됩니다.':'함께 모험할 친구를 골라 주세요. 첫 선택은 무료예요.'}}</p><div class="character-options"><button v-for="c in characters" :key="c.id" type="button" :class="['character-choice',{chosen:modelValue===c.id}]" :style="{'--character-color':c.color}" :disabled="unavailable(c)||busy||(locked&&modelValue!==c.id&&s.data.coins<5000)" :aria-pressed="modelValue===c.id" :aria-label="c.name+(unavailable(c)?' · Lv.30 잠금':' 선택')" @click="choose(c)"><span class="choice-status">{{unavailable(c)?(s.data.pet.character==='diglett'?'🔒 복구 필요':'🔒 Lv.30'):modelValue===c.id?'✓ 선택됨':locked?'5,000 P':'SELECT'}}</span><img :src="c.image" :alt="c.name" draggable="false"/><strong>{{c.name}} <small v-if="c.id==='mew'">NEW</small></strong><span class="character-type">{{c.type}}</span></button></div><p v-if="!signup&&s.data.pet.character==='diglett'">🔒 먼저 디그다를 복구하면 파트너를 변경할 수 있어요.</p><p class="character-hint">{{locked?'보유 포인트 '+s.data.coins.toLocaleString()+' P · 퀴즈로 포인트를 모아 주세요.':'파트너 변경에는 5,000포인트가 필요합니다.'}}</p><div v-if="pending" class="partner-change-confirm" role="dialog" aria-label="파트너 변경 확인"><h3>{{pending.name}}로 변경할까요?</h3><p>5,000포인트가 차감되며 새 캐릭터는 강화 전 1단계로 시작합니다. 변경 후 잔액 {{(s.data.coins-5000).toLocaleString()}} P</p><button type="button" :disabled="busy" @click="change">{{busy?'변경 중…':'5,000 P 사용하고 변경'}}</button><button type="button" class="light" :disabled="busy" @click="pending=null">취소</button><p v-if="error" role="alert">{{error}}</p></div></fieldset></template>

<style scoped>
.character-picker{min-width:0;width:100%;box-sizing:border-box}.character-picker .character-options{display:grid;grid-template-columns:repeat(5,minmax(0,1fr))!important;width:100%;max-width:none;gap:clamp(5px,.8vw,12px)}.character-picker .character-choice{min-width:0;width:100%;max-width:none;box-sizing:border-box;overflow:hidden;padding:28px 6px 12px!important}.character-picker .character-choice img{display:block;width:100%;max-width:130px;height:clamp(58px,9vw,130px)!important;object-fit:contain;margin:0 auto}.character-picker .character-choice strong{font-size:clamp(10px,1.2vw,17px);white-space:normal;overflow-wrap:anywhere}.character-picker .character-choice strong small{display:block;font-size:8px;color:#bc1757}.character-picker .choice-status{max-width:calc(100% - 8px);font-size:clamp(6px,.65vw,9px)!important;white-space:nowrap;letter-spacing:0}.character-picker .character-type{max-width:100%;font-size:clamp(7px,.7vw,10px);padding:2px 3px;box-sizing:border-box;white-space:normal}.character-choice:disabled{cursor:not-allowed}.character-choice[aria-label*="잠금"] img{filter:grayscale(.6);opacity:.6}@media(max-width:600px){.character-picker .character-options{gap:5px}.character-picker .character-choice{padding:23px 3px 8px!important}.character-picker .character-choice img{height:58px!important}.character-picker .character-choice strong{font-size:9px}.character-picker .character-type{font-size:6px}.character-picker .choice-status{font-size:6px!important;top:6px;right:3px}.character-picker .character-choice strong small{font-size:6px}}
</style>
